export interface Post {
  id: number
  title: string
  content: string
  createdAt: Date
}

const posts: Post[] = []

let nextId = 1

export function getPosts(): Post[] {
  return [...posts].sort(
    (a, b) => b.createdAt.getTime() - a.createdAt.getTime()
  )
}

export function createPost(title: string, content: string): Post {
  const post: Post = {
    id: nextId++,
    title,
    content,
    createdAt: new Date(),
  }
  posts.push(post)
  return post
}

